package com.mavric.health.billing.application;
import java.util.*;
import java.math.BigDecimal;
import org.junit.jupiter.api.*;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.mavric.health.audit.TraceContext;
import com.mavric.health.identity.*;
import com.mavric.health.tenancy.TenantRef;
import com.mavric.health.shared.*;
import com.mavric.health.billing.domain.Requests.Post;
import com.mavric.health.persistence.sqlserver.*;
import com.mavric.health.persistence.sqlserver.SqlServerFinanceStoreTest.Fixture;
import tools.jackson.databind.ObjectMapper;
import static com.mavric.health.persistence.sqlserver.SqlServerFinanceStoreTest.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Offline service/adapter tests; modeled replay is not proof of V6 locks or durable idempotency. */
class FinanceServiceSqlServerTest {
 final Fixture f=new Fixture();final Access access=mock(Access.class);final Sql sql=mock(Sql.class);final FinanceService service=new FinanceService(f.store,access);
 FinanceServiceSqlServerTest(){actor("CAJ");}
 void actor(String role){f.actor(role);doReturn(f.actor).when(access).actor();TraceContext.REQUEST.set(f.request);}
 @AfterEach void clean(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 @Test void cajAudReadGatesAndExactNumberWithoutBranchOrWriteGate(){for(String role:List.of("CAJ","AUD")){actor(role);f.balance=new BigDecimal("-99999999999999999999999999999999999999");var out=(Map<?,?>)service.balance(PATIENT);assertSame(f.balance,out.get("balanceMinor"));assertEquals(List.of(),service.movements(PATIENT));}verify(access,times(4)).roles("CAJ","AUD");verify(access,times(4)).module("FINANCE");verify(access,never()).write(anyString(),any(String[].class));verify(access,never()).branch(anyString());verifyNoInteractions(sql);}
 @Test void movementsSingleSpPatientExistenceAndNoBalancePreflight(){doThrow(new RuntimeException(new java.sql.SQLException("private driver canary",null,51002))).when(f.executor).execute(eq(SqlServerProcedure.FINANCE_MOVEMENTS),any(),eq(PATIENT));assertEquals(404,assertThrows(ApiException.class,()->service.movements(PATIENT)).status);verify(f.executor).execute(eq(SqlServerProcedure.FINANCE_MOVEMENTS),any(),eq(PATIENT));verifyNoMoreInteractions(f.executor);verifyNoInteractions(sql);}
 @Test void postUsesWriteCajAndSingleSpNoReadAfterWrite(){var row=(Map<?,?>)service.post(input(),KEY);assertEquals(12,row.size());assertEquals(input().patientId(),row.get("patientId"));verify(access).write("FINANCE","CAJ");assertEquals(List.of(SqlServerProcedure.FINANCE_POST),f.calls);assertEquals(1,Collections.frequency(f.manager.events,"begin:0"));assertEquals(1,Collections.frequency(f.manager.events,"commit"));verifyNoInteractions(sql);}
 @Test void readAndWriteRoleMatricesDenyBeforeExecutor(){for(String role:List.of("ADM","PRO","REC","PAC","RES","SAD","SOP")){actor(role);assertEquals(403,assertThrows(ApiException.class,()->service.balance(PATIENT)).status);assertEquals(403,assertThrows(ApiException.class,()->service.movements(PATIENT)).status);assertEquals(403,assertThrows(ApiException.class,()->service.post(input(),KEY)).status);}actor("AUD");assertEquals(403,assertThrows(ApiException.class,()->service.post(input(),KEY)).status);verifyNoInteractions(f.executor,sql);}
 @Test void missingRequest401ActorMismatchAndMalformedHostStopAllEffects(){TraceContext.REQUEST.remove();assertEquals(500,assertThrows(ApiException.class,()->service.balance(PATIENT)).status);actor("CAJ");doThrow(new ApiException(401,"UNAUTHENTICATED","Safe")).when(access).actor();assertEquals(401,assertThrows(ApiException.class,()->service.post(input(),KEY)).status);actor("CAJ");f.request.removeAttribute("health.actor");f.request.addHeader("X-Roles","CAJ");assertEquals(403,assertThrows(ApiException.class,()->service.movements(PATIENT)).status);actor("CAJ");f.request.setAttribute("health.tenant","bad");assertEquals(500,assertThrows(ApiException.class,()->service.balance(PATIENT)).status);actor("CAJ");f.request.setAttribute("health.tenant",new TenantRef(OTHER,"Foreign","foreign","CLINIC","HUMAN","ACTIVE",List.of("FINANCE")));assertEquals(403,assertThrows(ApiException.class,()->service.post(input(),KEY)).status);verifyNoInteractions(f.executor,sql);}
 @Test void financeModuleReadAndWriteSuspensionGuardStopBeforeInvalidInput(){doThrow(new ApiException(403,"MODULE_NOT_INCLUDED","Safe")).when(access).module("FINANCE");assertEquals(403,assertThrows(ApiException.class,()->service.balance("bad")).status);assertEquals(403,assertThrows(ApiException.class,()->service.movements("bad")).status);doThrow(new ApiException(403,"SUSPENDED","Safe")).when(access).write("FINANCE","CAJ");assertEquals("SUSPENDED",assertThrows(ApiException.class,()->service.post(null,null)).code);verifyNoInteractions(f.executor,sql);}
 @Test void invalidInputsNeverQueryOrCreateAndNoLegacyFallback(){assertEquals(400,assertThrows(ApiException.class,()->service.balance("bad")).status);assertEquals(400,assertThrows(ApiException.class,()->service.movements("bad")).status);assertEquals(400,assertThrows(ApiException.class,()->service.post(null,KEY)).status);assertEquals(400,assertThrows(ApiException.class,()->service.post(input(),"bad")).status);verifyNoInteractions(f.executor,sql);}
 @Test void sameKeyReplayDifferentKeyAndHashConflictAreExplicitlyModeledOnly(){reset(f.executor);var cache=new HashMap<String,Map<String,Object>>();doAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());assertEquals(SqlServerProcedure.FINANCE_POST,inv.getArgument(0));Object[] args=(Object[])inv.getRawArguments()[2];String key=(String)args[2],hash=(String)args[3];if(cache.containsKey(key)){var existing=cache.get(key);if(!hash.equals(existing.get("requestHash")))throw new RuntimeException(new java.sql.SQLException("private conflict canary",null,51003));return result(List.of(existing));}var body=f.mapper.readValue((String)args[1],Map.class);var row=movement();row.putAll(body);row.put("amountMinor",((Number)body.get("amountMinor")).longValue());row.put("id",args[0]);row.put("requestKey",key);row.put("requestHash",hash);cache.put(key,row);return result(List.of(row));}).when(f.executor).execute(any(),any(),any(Object[].class));var first=(Map<?,?>)service.post(input(),KEY);var replay=(Map<?,?>)service.post(input(),KEY);assertEquals(first,replay);var second=(Map<?,?>)service.post(input(),"another-key-001");assertNotEquals(first.get("id"),second.get("id"));var changed=new Post(PATIENT,"CHARGE",125,"Changed synthetic title",null);var error=assertThrows(ApiException.class,()->service.post(changed,KEY));assertEquals(409,error.status);assertNull(error.getCause());verify(f.executor,times(4)).execute(eq(SqlServerProcedure.FINANCE_POST),any(),any(Object[].class));verifyNoInteractions(sql);}
 @Test void paymentRefundErrorsAreSpAuthorityNotJavaLedgerReads(){doThrow(new RuntimeException(new java.sql.SQLException("private ledger canary",null,51003))).when(f.executor).execute(eq(SqlServerProcedure.FINANCE_POST),any(),any(Object[].class));for(Post p:List.of(new Post(PATIENT,"PAYMENT",10,"Synthetic",null),new Post(PATIENT,"REFUND",10,"Synthetic",OTHER))){var error=assertThrows(ApiException.class,()->service.post(p,KEY));assertEquals(409,error.status);assertFalse(error.toString().contains("canary"));}verify(f.executor,times(2)).execute(eq(SqlServerProcedure.FINANCE_POST),any(),any(Object[].class));verify(f.executor,never()).execute(eq(SqlServerProcedure.FINANCE_BALANCE),any(),any(Object[].class));verifyNoInteractions(sql);}
 @Test void commitMappingAndOuterCancellationNeverReturnPartialSuccess(){f.results.add(result(List.of(Map.of("balanceMinor",0.1,"currency","PEN"))));assertEquals(500,assertThrows(ApiException.class,()->service.balance(PATIENT)).status);assertEquals("rollback",f.manager.events.getLast());f.manager.failCommit=true;assertEquals(500,assertThrows(ApiException.class,()->service.post(input(),KEY)).status);assertThrows(RuntimeException.class,()->f.manager.outer(()->{service.post(input(),KEY);throw new RuntimeException("cancel");}));assertEquals("rollback",f.manager.events.getLast());assertSame(f.actor,f.request.getAttribute("health.actor"));verifyNoInteractions(sql);}
 @Test void minimalSpringSelectsLegacyAndLegacyMovementsRetainBalancePreflight(){when(sql.one(anyString(),any(Object[].class))).thenAnswer(inv->Map.of("balanceMinor",0L,"currency","PEN"));when(sql.rows(anyString(),any(Object[].class))).thenReturn(List.of());when(access.tenantId()).thenReturn(TENANT);try(var context=new AnnotationConfigApplicationContext()){context.registerBean(Sql.class,()->sql);context.registerBean(Access.class,()->access);context.registerBean(FinanceService.class);context.refresh();var legacy=context.getBean(FinanceService.class);assertEquals(List.of(),legacy.movements(PATIENT));verify(sql,times(2)).one(anyString(),any(Object[].class));verify(sql).rows(anyString(),eq(TENANT),eq(PATIENT));assertEquals(0,context.getBeanNamesForType(SqlServerFinanceStore.class).length);assertEquals(0,context.getBeanNamesForType(javax.sql.DataSource.class).length);}verifyNoInteractions(f.executor);}
}
